<script setup lang="ts">import {ref,computed,watch} from 'vue';import type {Corpus,Document,User,Page} from '../types/domain';import {corpusApi} from '../api/corpora';import {useAsync} from '../hooks/useAsync';import PageTitle from '../components/common/PageTitle.vue';import Table from '../components/common/Table.vue';import Notice from '../components/common/Notice.vue';import Empty from '../components/common/Empty.vue';const props=defineProps<{corpora:Corpus[];whitelist:string[];user:User;reload:()=>Promise<any>}>();const corpusId=ref(0),show=ref(false),name=ref(''),raw=ref(''),batchRaw=ref(''),edit=ref<Document|null>(null),title=ref(''),text=ref(''),page=ref(1),q=ref(''),docs=ref<Page<Document>|null>(null),docsError=ref('');const active=computed(()=>corpusId.value||props.corpora[0]?.id),pages=computed(()=>docs.value?Math.max(1,Math.ceil(docs.value.total/docs.value.page_size)):1);const {task,act}=useAsync();function choose(d:Document){edit.value=d;title.value=d.title;text.value=d.tokens_text}
async function loadDocs(){if(!active.value){docs.value=null;return}try{docs.value=await corpusApi.documents(active.value,q.value.trim(),page.value,40);docsError.value=''}catch(e:any){docsError.value=e.message}}
watch([active,page],loadDocs,{immediate:true});let timer:any=null;watch(q,()=>{clearTimeout(timer);timer=setTimeout(()=>{page.value=1;loadDocs()},350)});
async function submit(){await act(async()=>{const documents=raw.value.trim()?JSON.parse(raw.value):[];await corpusApi.create({name:name.value,filename:name.value+'.json',description:'编辑导入的已分词摘要',documents});await props.reload();show.value=false;raw.value=''},'分词语料已建立，可继续分批追加')};
async function append(){await act(async()=>{const r=await corpusApi.append(active.value,JSON.parse(batchRaw.value));batchRaw.value='';await props.reload();await loadDocs();return r},'批次已追加')};
</script><template><PageTitle index="02 / TOKEN CORPUS" title="词已经分好，口径仍要核对。" description="只按空白切词，精确匹配固定50词白名单；不做中文自动分词。同一语料可分批追加至百万篇，全库统计不抽样不截断。白名单后或min_df后空词文档单独记录，不伪造主题得分。"><button v-if="user.role!=='viewer'" @click="show=!show">导入分词语料 ↗</button></PageTitle><Notice :error="task.error||docsError" :message="task.message"/><form class="editor" v-if="show" @submit.prevent="submit"><h2>建立语料（可空首批，之后分批追加）</h2><label>语料名称<input v-model="name" required maxlength="100"/></label><label>首批文档JSON数组（可留空，每批≤1000篇）<textarea rows="5" v-model="raw" placeholder='[{"reference":"DOC-001","title":"展签摘要","tokens_text":"陶土 材料 工艺"},…]'/></label><button class="primary" :disabled="task.busy">校验并建立</button></form><div class="source-selector"><label>当前语料<select v-model="corpusId"><option :value="0" v-if="corpora[0]">默认 / {{corpora[0].name}}</option><option v-for="c in corpora" :key="c.id" :value="c.id">{{c.name}} / {{c.document_count}}篇</option></select></label><p>{{corpora.find(c=>c.id===active)?.description}}<br/>{{corpora.find(c=>c.id===active)?.filename}}</p></div><div class="whitelist"><small>FIXED WHITELIST / 精确匹配</small><p>{{whitelist.join(' · ')}}</p></div><form v-if="user.role!=='viewer'" class="editor" @submit.prevent="append"><h2>向当前语料追加一批（1–1000篇/批）</h2><label>批次文档JSON数组<textarea rows="4" v-model="batchRaw" required placeholder='[{"reference":"DOC-101","title":"展签摘要","tokens_text":"档案 记忆 年代"},…]'/></label><p>分批导入同一语料；批次内reference不可重复，与库内重复整批拒绝。词频与筛词始终按全库统计。</p><button class="primary" :disabled="task.busy||!corpora.length">校验并追加批次</button></form><form v-if="edit" class="editor" @submit.prevent="act(async()=>{await corpusApi.edit(edit!.id,{title,tokens_text:text});await reload();await loadDocs();edit=null},'分词文档已修订，历史运行保持原结果')"><h2>修订 {{edit.reference}}</h2><label>标题<input v-model="title" maxlength="120" required/></label><label>已分词文本<textarea rows="4" v-model="text" maxlength="10000"/></label><button class="primary" :disabled="task.busy">保存修订</button></form><div class="section-title"><h2>原始文档 / 分页核对</h2><small>共 {{docs?.total??0}} 篇 · 第 {{page}} / {{pages}} 页 · 计算始终用全部</small></div><label class="browser-search"><input v-model="q" placeholder="按展签编号前缀查找，如 ZC-0001"/></label><Table v-if="docs&&docs.items.length" :headers="['文档 / 标题','空白分词摘要','']"><tr v-for="d in docs.items" :key="d.id"><td><small>{{d.reference}}</small><strong>{{d.title}}</strong></td><td class="token-text">{{d.tokens_text||'（空词文档）'}}</td><td><button v-if="user.role!=='viewer'" class="text-button" @click="choose(d)">编辑分词 ↗</button></td></tr></Table><Empty v-else title="没有匹配的文档" help="调整编号前缀，或先分批导入。"/><div class="pager" v-if="docs&&docs.total>0"><button :disabled="page<=1" @click="page--">← 上一页</button><small>第 {{page}} / {{pages}} 页 · 每页 40 篇</small><button :disabled="page>=pages" @click="page++">下一页 →</button></div></template>
